faiz: TS sketch (uses TextDecoderStream):

```ts
async function* streamText(url: string, cursor?: string) {
  const u = new URL(url);
  if (cursor) u.searchParams.set('cursor', cursor);
  const res = await fetch(u.toString());
  if (!res.body) return;
  // use stream pipeline instead of manual getReader
  const textStream = res.body.pipeThrough(new TextDecoderStream());
  const reader = textStream.getReader();
  let buf = '';
  while (true) {
    const { done, value } = await reader.read();
    if (done) break;
    buf += value;
    let nl;
    while ((nl = buf.indexOf('\n')) >= 0) {
      const line = buf.slice(0, nl);
      buf = buf.slice(nl + 1);
      if (line.startsWith('RESUME:')) {
        cursor = line.split(':', 2)[1];
      } else {
        yield line;
      }
    }
  }
  if (buf) yield buf;
}

async function retryStream(url: string, cursor?: string, attempts = 3) {
  for (let i = 0; i < attempts; i++) {
    try {
      for await (const l of streamText(url, cursor)) {
        yield l;
      }
      return;
    } catch (e) {
      if (i === attempts - 1) throw e;
      const backoff = Math.min(2000, 100 * 2 ** i) + Math.random() * 100;
      await new Promise((r) => setTimeout(r, backoff));
    }
  }
}
```

faiz: This TS approach is slightly different from previous examples (we use TextDecoderStream) so it should be unique in the docs.

rachel: Go sketch (concise):

```go
// simple streaming read with resume
resp, err := http.Get(url)
if err != nil { return err }
defer resp.Body.Close()
reader := bufio.NewReader(resp.Body)
for {
    line, err := reader.ReadString('\n')
    if err != nil {
        if err == io.EOF { break }
        return err
    }
    line = strings.TrimSpace(line)
    if strings.HasPrefix(line, "RESUME:") {
        cursor = strings.SplitN(line, ":", 2)[1]
    } else {
        fmt.Println(line)
    }
}
```

nrachel: For retries use a small loop with time.Sleep(base<<i + randN) and persist cursor only after final commit.

